@startuml

class User {
  + ID : int
  + Name : string
  + Address : string
  + Birthday : date
}

class BusinessOwner extends User {
  + LinkedInAccount : string
}

class HungryCustomer extends User {
  + DeliveryAddress : string
}

class Entertainer extends User {
  + StageName : string
  + Bio : string
  + PricePer30Minutes : float
}

class PizzaRestaurant {
  + ZipCode : string
  + Address : string
  + PhoneNumber : string
  + Website : string
  + OpeningHours : string
}

class Pizza {
  + Name : string
  + CrustStructure : string
  + Price : float
}

class Order {
  + ID : int
  + OrderDateTime : datetime
  + LatestDeliveryTime : time
  + NumberOfPeople : int
}

class EntertainmentOrder extends Order {
  + EntertainmentType : string
  + Duration : int
}

class EntertainerAvailability {
  + Day : string
}

BusinessOwner "1" -- "0..*" PizzaRestaurant : owns
PizzaRestaurant "1" -- "1..*" Pizza : offers
HungryCustomer "1" -- "0..*" Order : makes
Order "1" -- "1..*" Pizza : contains
EntertainmentOrder "0..*" -- "1" Entertainer : fulfilled by
Entertainer "0..*" -- "0..*" PizzaRestaurant : works for
Entertainer "1" -- "1..*" EntertainerAvailability : has
PizzaRestaurant "1" -- "0..*" EntertainerAvailability : has

@enduml

